/usr/bin/bash -lc "python3 - <<'PY'
from pathlib import Path
from collections import defaultdict
c={};id=''
for s in Path('lean/claims.yaml').read_text().splitlines():
 if s.startswith('- id: '):id=s[6:]
 if s.startswith('  file: '):c[id]=Path(s[8:]).stem
rows=[];r=None
for i,s in enumerate(Path('lean/coverage.yaml').read_text().splitlines(),1):
 if s=='- paper:':
  if r:rows.append(r)
  r={'line':i,'class':'','conclusion':'full (implicit)','claims':[]}
 if r:
  if s.startswith('    label: '):r['label']=s[11:]
  if s.startswith('  class: '):r['class']=s[9:]
  if s.startswith('  conclusion: '):r['conclusion']=s[14:]
  if s.startswith('  - stratonovich-'):r['claims'].append(s[4:])
rows.append(r)
mods=defaultdict(set)
for r in rows:
 for k in r['claims']:
  if k in c:mods[c[k]].add((r['label'],r['class'],r['conclusion'],r['line']))
for i,s in enumerate(Path('candidate/statement-ledger.md').read_text().splitlines(),1):
 if s.startswith('## ') and ('(whole result)' in s or '(narrower result' in s):
  m=s.split()[1];print(m, 'A' if '(whole result)' in s else 'B', '; '.join(f'{a} {b}/{v} @{n}' for a,b,v,n in sorted(mods[m])))
PY"

